SELECT EMPLID, EMPL_RCD, EFFDT, EFFSEQ, GVT_AWD_CLASS, OTH_PAY, OTH_HRS, GOAL_AMT, EARNINGS_END_DT, GVT_USE_BY_DATE, GVT_AWARD_GROUP, GVT_TANG_BEN_AMT, GVT_INTANG_BEN_AMT, GVT_SUGGESTION_NBR, GVT_OBLIG_EXPIR_DT, GL_PAY_TYPE, ACCT_CD, ERNCD, GVT_SEPCHK_IND, SEPCHK, DED_TAKEN, DED_TAKEN_GENL, DISABLE_DIR_DEP, GROSSUP, ADDL_SEQ, COMMENTS
FROM {{ ref('stg_ehrp2biis__ps_gvt_awd_data') }}
QUALIFY ROW_NUMBER() OVER (
    PARTITION BY EMPLID, EMPL_RCD, EFFDT, EFFSEQ
    ORDER BY EMPLID ASC NULLS LAST, EMPL_RCD ASC NULLS LAST, EFFDT ASC NULLS LAST, EFFSEQ ASC NULLS LAST, GVT_AWD_CLASS ASC NULLS LAST, OTH_PAY ASC NULLS LAST, OTH_HRS ASC NULLS LAST, GOAL_AMT ASC NULLS LAST, EARNINGS_END_DT ASC NULLS LAST, GVT_USE_BY_DATE ASC NULLS LAST, GVT_AWARD_GROUP ASC NULLS LAST, GVT_TANG_BEN_AMT ASC NULLS LAST, GVT_INTANG_BEN_AMT ASC NULLS LAST, GVT_SUGGESTION_NBR ASC NULLS LAST, GVT_OBLIG_EXPIR_DT ASC NULLS LAST, GL_PAY_TYPE ASC NULLS LAST, ACCT_CD ASC NULLS LAST, ERNCD ASC NULLS LAST, GVT_SEPCHK_IND ASC NULLS LAST, SEPCHK ASC NULLS LAST, DED_TAKEN ASC NULLS LAST, DED_TAKEN_GENL ASC NULLS LAST, DISABLE_DIR_DEP ASC NULLS LAST, GROSSUP ASC NULLS LAST, ADDL_SEQ ASC NULLS LAST, COMMENTS ASC NULLS LAST
) = 1
